 80	     * 즉시 구매 입찰을 생성합니다.
 81	     *
 82	     * @param requestDto 즉시 구매 요청 정보
 83	     * @return 생성된 주문 ID
 84	     * @throws OrderBidAccessDeniedException 주문 입찰에 대한 접근 권한이 없는 경우
 85	     * @throws InvalidOrderBidDataException 주문 입찰 정보가 유효하지 않은 경우
 86	     * @throws SaleBidNotFoundException 판매 입찰을 찾을 수 없는 경우
 87	     * @throws OrderBidCreationFailedException 주문 입찰 생성 실패 시
 88	     */
 89	    @PostMapping("/instant")
 90	    public ResponseEntity<ResponseDto<Long>> createInstantOrderBid(@RequestBody @Valid InstantOrderRequestDto requestDto) {
 91	        // 사용자 이메일 추출 및 검증
 92	        String email = SecurityUtils.extractAndValidateEmailForOrderBid("즉시 구매 입찰 생성");
 93	
 94	        log.info("사용자 [{}]가 판매 입찰(ID: {})에 대한 즉시 구매를 요청합니다. 창고 보관 여부: {}",
 95	                email, requestDto.getSaleBidId(), requestDto.isWarehouseStorage());
 96	
 97	        // 결제 정보 보강
 98	        PaymentRequestDto paymentRequest = enrichPaymentRequest(requestDto.getPaymentRequest(), email);
 99	
100	        // 서비스 호출
101	        Long orderId = orderBidCommandService.createInstantOrderBid(
102	                email,
103	                requestDto.getSaleBidId(),
104	                requestDto.getAddressId(),
105	                requestDto.isWarehouseStorage(),
106	                paymentRequest
107	        ).getId();
108	
109	        return ResponseEntity.ok(ResponseDto.success(orderId, "즉시 구매가 성공적으로 처리되었습니다."));
110	    }
111	
112	    /**
113	     * 결제 요청 정보를 보강합니다.
114	     *
115	     * @param paymentRequest 결제 요청 정보
116	     * @param email 사용자 이메일
117	     * @return 보강된 결제 요청 정보
118	     */
119	    private PaymentRequestDto enrichPaymentRequest(PaymentRequestDto paymentRequest, String email) {
120	        paymentRequest.setUserEmail(email);
121	        paymentRequest.setOrderId(null); // 초기에는 null로 설정, 이후 Order 생성 후 업데이트 가능
122	        return paymentRequest;
123	    }
100	        orderBid.assignOrder(order);
101	
102	        return orderBidRepository.save(orderBid);
103	    }
104	
105	    /**
106	     * 즉시 구매 주문 입찰을 생성합니다.
107	     *
108	     * @param buyerEmail 구매자 이메일
109	     * @param saleBidId 판매 입찰 ID
110	     * @param addressId 배송지 ID
111	     * @param isWarehouseStorage 창고 보관 여부
112	     * @param paymentRequest 결제 요청 정보
113	     * @return 생성된 주문 입찰
114	     * @throws OrderBidCreationFailedException 주문 입찰 생성 실패 시
115	     * @throws SaleBidNotFoundException 판매 입찰을 찾을 수 없는 경우
116	     * @throws InvalidOrderBidDataException 주문 입찰 정보가 유효하지 않은 경우
117	     */
118	    @Transactional
119	    public OrderBid createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
120	                                          boolean isWarehouseStorage, PaymentRequestDto paymentRequest) {
121	        try {
122	            // 1. 입력값 검증
123	            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);
124	
125	            // 2. 유저 조회
126	            User buyer = userQueryService.findByEmail(buyerEmail);
127	
128	            // 3. SaleBid 및 Sale 조회
129	            SaleBid saleBid = getSaleBidAndValidate(saleBidId);
130	            Sale sale = saleBid.getSale();
131	
132	            // 4. Order 생성
133	            Order order = orderCommandService.createInstantOrder(
134	                    buyer,
135	                    saleBid,
136	                    addressId,
137	                    isWarehouseStorage,
138	                    paymentRequest
139	            );
140	
141	            // 5. OrderBid 생성 및 저장
142	            OrderBid orderBid = createInstantOrderBid(order, saleBid, sale);
143	
144	            return orderBid;
145	        } catch (Exception e) {
146	            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
147	            return null; // 실행되지 않음 (예외가 던져짐)
148	        }
149	    }
150	
151	    /**
152	     * 즉시 구매 입력값을 검증합니다.
153	     */
154	    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, PaymentRequestDto paymentRequest) {
155	        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
156	            throw new OrderBidAccessDeniedException("구매자 이메일이 없습니다.");
157	        }
158	        if (saleBidId == null) {
159	            throw new SaleBidNotFoundException("판매 입찰 ID가 없습니다.");
160	        }
161	        if (addressId == null) {
162	            throw new InvalidOrderBidDataException("배송지 ID가 없습니다.");
163	        }
164	        if (paymentRequest == null) {
165	            throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
166	        }
167	    }
168	
169	    /**
170	     * SaleBid를 조회하고 유효성을 검증합니다.
171	     */
172	    private SaleBid getSaleBidAndValidate(Long saleBidId) {
173	        SaleBid saleBid = saleBidQueryService.findById(saleBidId);
174	        if (saleBid == null) {
175	            throw new SaleBidNotFoundException("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
176	        }
177	
178	        Sale sale = saleBid.getSale();
179	        if (sale == null) {
180	            throw new InvalidOrderBidDataException("판매 입찰과 연결된 판매 정보가 없습니다.");
181	        }
182	
183	        return saleBid;
184	    }
185	
186	    /**
187	     * 즉시 구매 OrderBid를 생성합니다.
188	     */
189	    private OrderBid createInstantOrderBid(Order order, SaleBid saleBid, Sale sale) {
190	        ProductSize productSize = saleBid.getProductSize();
191	
192	        OrderBid orderBid = OrderBid.builder()
193	                .user(order.getUser()) // 구매자
194	                .productSize(productSize)
195	                .bidPrice(saleBid.getBidPrice())
196	                .status(BidStatus.MATCHED) // 즉시 구매는 바로 매칭 상태
197	                .order(order) // Order와 매핑
198	                .sale(sale) // 셀러 정보 추가
199	                .build();
200	
201	        // 양방향 관계 설정
202	        orderBid.assignOrder(order);
203	
204	        // 플래그 설정 및 저장
205	        orderBid.markAsInstantPurchase();
206	        return orderBidRepository.save(orderBid);
207	    }
208	
209	    /**
210	     * 주문 입찰 생성 예외를 처리합니다.
211	     */
212	    private void handleOrderBidCreationException(Exception e, String operation) {
213	        if (e instanceof OrderException) {
214	            throw (OrderException) e;
215	        }
216	        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
217	        throw new OrderBidCreationFailedException(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
218	    }
219	
220	    /**
221	     * 주문 입찰을 매칭 상태로 업데이트합니다.
222	     *
223	     * @param orderBid 주문 입찰
224	     * @throws InvalidOrderBidStatusException 주문 입찰 상태가 유효하지 않은 경우
225	     * @throws OrderBidMatchingFailedException 주문 입찰 매칭 실패 시
226	     */
227	    @Transactional
228	    public void matchOrderBid(OrderBid orderBid) {
229	        try {
230	            if (orderBid == null) {
231	                throw new OrderBidNotFoundException("주문 입찰 정보가 없습니다.");
232	            }
233	
234	            if (orderBid.getStatus() == BidStatus.MATCHED) {
235	                throw new OrderBidAlreadyMatchedException("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
236	            }
237	
238	            orderBid.updateStatus(BidStatus.MATCHED);
239	        } catch (Exception e) {
240	            if (e instanceof OrderException) {
241	                throw e;
242	            }
243	            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
244	            throw new OrderBidMatchingFailedException("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
245	        }
246	    }
247	
248	    /**
249	     * 주문 입찰을 삭제합니다.
250	     *
251	     * @param orderBidId 주문 입찰 ID
252	     * @throws OrderBidNotFoundException 주문 입찰을 찾을 수 없는 경우
253	     * @throws OrderBidAlreadyMatchedException 이미 매칭된 주문 입찰인 경우
254	     * @throws OrderBidDeletionFailedException 주문 입찰 삭제 실패 시
255	     */
256	    @Transactional
257	    public void deleteOrderBid(Long orderBidId) {
258	        try {
259	            // OrderBid 조회
260	            OrderBid orderBid = orderBidRepository.findById(orderBidId)
261	                    .orElseThrow(() -> new OrderBidNotFoundException("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));
262	
263	            // Sale과 연결 여부 확인
264	            if (orderBid.getSale() != null) {
265	                throw new OrderBidAlreadyMatchedException("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
266	            }
267	
268	            // 매칭 상태 확인
269	            if (orderBid.getStatus() == BidStatus.MATCHED) {
270	                throw new OrderBidAlreadyMatchedException("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
271	            }
272	
273	            // Order와 연결 여부 확인 후 삭제
274	            if (orderBid.getOrder() != null) {
275	                orderCommandService.deleteOrder(orderBid.getOrder().getId());
276	            }
277	
278	            // OrderBid 삭제
279	            orderBidRepository.delete(orderBid);
280	        } catch (Exception e) {
281	            if (e instanceof OrderException) {
282	                throw e;
283	            }
284	            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
285	            throw new OrderBidDeletionFailedException("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
286	        }
287	    }
  1	package com.fream.back.domain.order.entity;
  2	
  3	import com.fream.back.domain.product.entity.ProductSize;
  4	import com.fream.back.domain.sale.entity.Sale;
  5	import com.fream.back.domain.user.entity.User;
  6	import com.fream.back.global.entity.BaseTimeEntity;
  7	import jakarta.persistence.*;
  8	import lombok.AllArgsConstructor;
  9	import lombok.Builder;
 10	import lombok.Getter;
 11	import lombok.NoArgsConstructor;
 12	
 13	/**
 14	 * 주문 입찰 엔티티
 15	 */
 16	@Entity
 17	@Getter
 18	@NoArgsConstructor
 19	@AllArgsConstructor
 20	@Builder
 21	public class OrderBid extends BaseTimeEntity {
 22	
 23	    @Id
 24	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 25	    private Long id;
 26	
 27	    @ManyToOne(fetch = FetchType.LAZY)
 28	    @JoinColumn(name = "user_id")
 29	    private User user; // 구매자 정보
 30	
 31	    @ManyToOne(fetch = FetchType.LAZY)
 32	    @JoinColumn(name = "product_size_id")
 33	    private ProductSize productSize; // 구매 대상 상품 사이즈
 34	
 35	    private int bidPrice; // 입찰 가격
 36	
 37	    @Builder.Default
 38	    @Enumerated(EnumType.STRING)
 39	    private BidStatus status = BidStatus.PENDING; // 입찰 상태 (대기 중, 매칭 완료 등)
 40	
 41	    @OneToOne(fetch = FetchType.LAZY)
 42	    @JoinColumn(name = "order_id")
 43	    private Order order; // 매칭된 구매 엔티티
 44	
 45	    @OneToOne(fetch = FetchType.LAZY)
 46	    @JoinColumn(name = "sale_id")
 47	    private Sale sale; // 매칭된 판매 엔티티
 48	
 49	    // 즉시 구매 플래그
 50	    @Builder.Default
 51	    @Column(nullable = false)
 52	    private boolean isInstantPurchase = false;
 53	
 54	    /**
 55	     * Order와의 양방향 관계를 설정합니다.
 56	     * 기존 관계가 있다면 해제하고 새 관계를 설정합니다.
 57	     *
 58	     * @param order 연결할 Order 객체
 59	     */
 60	    public void assignOrder(Order order) {
 61	        // 기존 관계가 있으면 해제
 62	        if (this.order != null && this.order != order) {
 63	            Order oldOrder = this.order;
 64	            this.order = null;
 65	            if (oldOrder.getOrderBid() == this) {
 66	                oldOrder.assignOrderBid(null);
 67	            }
 68	        }
 69	
 70	        // 새 관계 설정
 71	        this.order = order;
 72	
 73	        // 매칭 상태로 변경
 74	        if (order != null) {
 75	            this.status = BidStatus.MATCHED;
 76	
 77	            // Order 쪽에도 관계 설정
 78	            if (order.getOrderBid() != this) {
 79	                order.assignOrderBid(this);
 80	            }
 81	        }
 82	    }
 83	
 84	    /**
 85	     * Sale과의 양방향 관계를 설정합니다.
 86	     *
 87	     * @param sale 연결할 Sale 객체
 88	     */
 89	    public void assignSale(Sale sale) {
 90	        this.sale = sale;
 91	        this.status = BidStatus.MATCHED;
 92	    }
 93	
 94	    /**
 95	     * 즉시 구매로 표시합니다.
 96	     */
 97	    public void markAsInstantPurchase() {
 98	        this.isInstantPurchase = true;
 99	    }
100	
101	    /**
102	     * 입찰 상태를 업데이트합니다.
103	     *
104	     * @param newStatus 새 입찰 상태
105	     */
106	    public void updateStatus(BidStatus newStatus) {
107	        this.status = newStatus;
108	    }
109	}package com.fream.back.domain.order.entity;
110	
111	import java.util.*;
112	
113	/**
114	 * 주문 상태를 정의하는 Enum
115	 */
116	public enum OrderStatus {
117	    PENDING_PAYMENT, // 결제 대기
118	    PAYMENT_COMPLETED, // 결제 완료
119	    PREPARING, // 상품 준비 중
120	    IN_WAREHOUSE, // 창고 보관 중
121	    SHIPMENT_STARTED, // 배송 시작
122	    IN_TRANSIT, // 배송 중
123	    COMPLETED, // 배송 완료
124	    REFUND_REQUESTED, // 환불 대기
125	    REFUNDED; // 환불 완료
126	
127	    // 각 상태에서 전이 가능한 다음 상태들을 정의
128	    private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED_TRANSITIONS = new HashMap<>();
129	
130	    static {
131	        // 상태 전이 규칙 초기화
132	        ALLOWED_TRANSITIONS.put(PENDING_PAYMENT, Set.of(PAYMENT_COMPLETED, COMPLETED, IN_WAREHOUSE));
133	        ALLOWED_TRANSITIONS.put(PAYMENT_COMPLETED, Set.of(PREPARING, REFUND_REQUESTED, IN_WAREHOUSE));
134	        ALLOWED_TRANSITIONS.put(PREPARING, Set.of(IN_WAREHOUSE, SHIPMENT_STARTED));
135	        ALLOWED_TRANSITIONS.put(IN_WAREHOUSE, Set.of(SHIPMENT_STARTED, COMPLETED));
136	        ALLOWED_TRANSITIONS.put(SHIPMENT_STARTED, Set.of(IN_TRANSIT));
137	        ALLOWED_TRANSITIONS.put(IN_TRANSIT, Set.of(COMPLETED));
